export default function (pi) {
  let dumps = 0;
  pi.registerTool({
    name: "dump", label: "Dump", description: "Oversized local output",
    parameters: { type: "object", properties: {} },
    async execute() {
      const sizes = [350000];
      const chars = sizes[Math.min(dumps++, sizes.length - 1)];
      return { content: [{ type: "text", text: `DUMP_HEAD ${"x".repeat(chars)} DUMP_TAIL` }, ...[]], details: {}, terminate: false };
    },
  });
}

export default function (pi) {
  pi.on("turn_end", (event) => {
    const index = event.toolResults.findIndex((result) => result.toolName === "dump");
    return index < 0 ? undefined : { entries: [...event.entries, { type: "context_edit", targetId: event.toolResultEntryIds[index], replacement: { content: [{ type: "text", text: "REDACTED" }] } }] };
  });
}
